import { useState } from 'react';

interface BlData {
  code: string;
  participants: number;
  reports: number;
}

interface Props {
  data: BlData[];
}

const BL_NAMES: Record<string, string> = {
  OE1: 'Wien',
  OE2: 'Salzburg',
  OE3: 'Niederösterreich',
  OE4: 'Burgenland',
  OE5: 'Oberösterreich',
  OE6: 'Steiermark',
  OE7: 'Tirol',
  OE8: 'Kärnten',
  OE9: 'Vorarlberg',
