   181→    res.status(201).json({ success: true });
   182→  } catch (e: any) {
   183→    if (e.message?.includes('UNIQUE') || e.message?.includes('PRIMARY')) {
   184→      res.status(409).json({ error: 'Umsetzer bereits aktiviert' });
   185→    } else {
   186→      throw e;
   187→    }
   188→  }
   189→});
   190→
   191→exercisesRouter.patch('/:id/repeaters/:rid', (req, res) => {
   192→  const db = getDb();
   193→  const { operator_callsign } = req.body;
   194→  db.prepare('UPDATE exercise_repeaters SET operator_callsign = ? WHERE exercise_id = ? AND repeater_id = ?')
