    97→// Get exercise stats
    98→exercisesRouter.get('/:id/stats', (req, res) => {
    99→  const db = getDb();
   100→  const eid = req.params.id;
   101→  const totalParticipants = (db.prepare('SELECT COUNT(DISTINCT operator_id) as c FROM signal_reports WHERE exercise_id = ? AND is_op_marker = 0').get(eid) as any)?.c || 0;
   102→  const totalReports = (db.prepare('SELECT COUNT(*) as c FROM signal_reports WHERE exercise_id = ? AND is_op_marker = 0 AND readability IS NOT NULL').get(eid) as any)?.c || 0;
   103→  const perRepeater = db.prepare(`
   104→    SELECT r.short_name, COUNT(*) as count
   105→    FROM signal_reports sr
   106→    JOIN repeaters r ON r.id = sr.repeater_id
   107→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0 AND sr.readability IS NOT NULL
   108→    GROUP BY sr.repeater_id
   109→    ORDER BY r.sort_order
   110→  `).all(eid);
   111→
   112→  // Bezirk breakdown: participants + reports per bezirk, grouped by bundesland
   113→  const bezirkStats = db.prepare(`
   114→    SELECT bl.name as bundesland, bl.code as bundesland_code, bl.sort_order as bl_sort,
   115→      bz.code as bezirk_code, bz.name as bezirk_name, bz.is_capital,
   116→      COUNT(DISTINCT sr.operator_id) as participants,
   117→      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as reports
   118→    FROM signal_reports sr
   119→    JOIN operators o ON o.id = sr.operator_id
   120→    JOIN bezirke bz ON bz.code = o.bezirk_code
   121→    JOIN bundeslaender bl ON bl.code = bz.bundesland_code
   122→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
   123→    GROUP BY bz.code
   124→    ORDER BY bl.sort_order, bz.code
   125→  `).all(eid);
   126→
   127→  // Bundesland breakdown (works even without bezirk_code, derives BL from callsign prefix)
   128→  const blStats = db.prepare(`
   129→    SELECT
   130→      COALESCE(bl.name, 'OE' || SUBSTR(o.callsign, 3, 1), 'Sonstige') as bundesland,
   131→      COALESCE(o.bundesland_code, '0' || SUBSTR(o.callsign, 3, 1)) as bundesland_code,
   132→      COUNT(DISTINCT sr.operator_id) as participants,
   133→      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as reports
   134→    FROM signal_reports sr
   135→    JOIN operators o ON o.id = sr.operator_id
   136→    LEFT JOIN bundeslaender bl ON bl.code = o.bundesland_code
   137→      OR (o.bundesland_code IS NULL AND bl.code = '0' || SUBSTR(o.callsign, 3, 1))
   138→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
   139→    GROUP BY COALESCE(o.bundesland_code, '0' || SUBSTR(o.callsign, 3, 1))
   140→    ORDER BY bundesland_code
   141→  `).all(eid);
   142→
   143→  // Participant list: all operators with their report counts
   144→  const participants = db.prepare(`
   145→    SELECT o.callsign, o.name, o.bezirk_code, o.bundesland_code,
   146→      COALESCE(bl.name, bl2.name) as bundesland_name,
   147→      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as report_count
   148→    FROM signal_reports sr
   149→    JOIN operators o ON o.id = sr.operator_id
   150→    LEFT JOIN bundeslaender bl ON bl.code = o.bundesland_code
   151→    LEFT JOIN bundeslaender bl2 ON o.bundesland_code IS NULL AND bl2.code = '0' || SUBSTR(o.callsign, 3, 1)
   152→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
   153→    GROUP BY sr.operator_id
   154→    ORDER BY COALESCE(bl.sort_order, bl2.sort_order), o.bezirk_code, o.callsign
   155→  `).all(eid);
   156→
   157→  res.json({ totalParticipants, totalReports, perRepeater, bezirkStats, blStats, participants });
   158→});
