   122→    FROM signal_reports sr
   123→    JOIN repeaters r ON r.id = sr.repeater_id
   124→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
   125→    GROUP BY sr.repeater_id ORDER BY r.sort_order
   126→  `).all(req.params.id) as any[];
   127→
   128→  let text = `BOS-ARSA Übung — ${exercise.date}\n`;
   129→  text += '='.repeat(60) + '\n';
   130→  text += `Teilnehmer: ${stats.participants}\n`;
   131→  text += `Rapporte gesamt: ${stats.reports}\n\n`;
   132→  text += 'Pro Frequenz:\n';
   133→  for (const r of perRepeater) {
